// Advanced sentiment analysis and issue classification
const customerInquiry = $input.item.json.customer_inquiry;
const customerProfile = $input.item.json.customer_profile;
const orderHistory = $input.item.json.order_history;

// Sentiment analysis keywords
const sentimentIndicators = {
  negative: ['disappointed', 'frustrated', 'angry', 'terrible', 'horrible', 'worst', 'unacceptable', 'refund', 'cancel'],
  neutral: ['question', 'inquiry', 'wondering', 'curious', 'information', 'help', 'assistance'],
  positive: ['love', 'amazing', 'beautiful', 'perfect', 'excellent', 'wonderful', 'impressed']
};

// Issue type classification
const issueKeywords = {
  quality: ['quality', 'damaged', 'defect', 'color', 'print', 'frame', 'scratched', 'bent'],
  shipping: ['shipping', 'delivery', 'tracking', 'delayed', 'lost', 'damaged in transit'],
  billing: ['charge', 'payment', 'refund', 'price', 'billing', 'invoice', 'cost'],
  product: ['size', 'description', 'expected', 'different', 'wrong item', 'not as shown'],
  general: ['question', 'information', 'how to', 'when will', 'status']
};

// Analyze sentiment
let sentimentScore = 0;
let detectedSentiment = 'neutral';

for (const [sentiment, keywords] of Object.entries(sentimentIndicators)) {
  const matches = keywords.filter(keyword => 
    customerInquiry.toLowerCase().includes(keyword.toLowerCase())
  ).length;

  if (sentiment === 'negative' && matches > 0) {
    sentimentScore = -matches;
    detectedSentiment = 'negative';
  } else if (sentiment === 'positive' && matches > 0 && sentimentScore >= 0) {
    sentimentScore = matches;
    detectedSentiment = 'positive';
  }
}

// Classify issue type
let detectedIssueType = 'general';
let maxMatches = 0;

for (const [issueType, keywords] of Object.entries(issueKeywords)) {
  const matches = keywords.filter(keyword => 
    customerInquiry.toLowerCase().includes(keyword.toLowerCase())
  ).length;

  if (matches > maxMatches) {
    maxMatches = matches;
    detectedIssueType = issueType;
  }
}

// Calculate customer value tier
const totalSpent = orderHistory?.total_spent || 0;
const orderCount = orderHistory?.orders_count || 0;
const avgOrderValue = orderCount > 0 ? totalSpent / orderCount : 0;

const customerTier = totalSpent > 1000 ? 'vip' :
                   totalSpent > 500 ? 'premium' :
                   totalSpent > 100 ? 'standard' : 'new';

// Determine urgency level
const urgencyFactors = {
  vip_customer: customerTier === 'vip' ? 3 : 0,
  negative_sentiment: sentimentScore < -2 ? 3 : sentimentScore < 0 ? 1 : 0,
  quality_issue: detectedIssueType === 'quality' ? 2 : 0,
  high_value: avgOrderValue > 300 ? 1 : 0,
  repeat_customer: orderCount > 3 ? 1 : 0
};

const urgencyScore = Object.values(urgencyFactors).reduce((sum, score) => sum + score, 0);
const urgencyLevel = urgencyScore >= 6 ? 'critical' :
                   urgencyScore >= 4 ? 'high' :
                   urgencyScore >= 2 ? 'medium' : 'low';

return {
  analysis_results: {
    sentiment: detectedSentiment,
    sentiment_score: sentimentScore,
    issue_type: detectedIssueType,
    issue_keywords_matched: maxMatches,
    customer_tier: customerTier,
    urgency_level: urgencyLevel,
    urgency_score: urgencyScore,
    urgency_factors: urgencyFactors
  },
  customer_insights: {
    total_spent: totalSpent,
    order_count: orderCount,
    avg_order_value: avgOrderValue,
    customer_since: customerProfile?.created_at,
    last_order: orderHistory?.last_order_date
  },
  next_action: urgencyLevel === 'critical' ? 'escalate_immediately' :
              urgencyLevel === 'high' ? 'priority_response' : 'standard_response'
};

